export const recordingMessages = { de, en };
for (const [locale, values] of Object.entries(compact)) {
  if (values.length !== compactKeys.length) throw new Error(`Invalid recording message row ${locale}: ${values.length}/${compactKeys.length}`);
  recordingMessages[locale] = { ...en, ...Object.fromEntries(compactKeys.map((key, index) => [key, values[index]])) };
}

const supplemental = buildRecordingSupplement();
for (const [locale, values] of Object.entries(supplemental)) {
  recordingMessages[locale] = { ...(recordingMessages[locale] || en), ...values };
}
